import{_ as i,C as o,o as e,c as r,ao as a,b as s,w as l,a as d,E as c,ap as h}from"./chunks/framework.CwDeSRWD.js";const A=JSON.parse('{"title":"Finite-element coupling","description":"","frontmatter":{},"headers":[],"relativePath":"fe_coupling/index.md","filePath":"fe_coupling/index.md","lastUpdated":null}'),f={name:"fe_coupling/index.md"};function g(u,t,m,p,y,b){const n=o("Mermaid");return e(),r("div",null,[t[1]||(t[1]=a('<h1 id="fe-coupling" tabindex="-1">Finite-element coupling <a class="header-anchor" href="#fe-coupling" aria-label="Permalink to &quot;Finite-element coupling {#fe-coupling}&quot;">​</a></h1><p>MeanFieldHomogenization used <strong>as a constitutive law inside a structural finite-element computation</strong> — the role an MFront behavior or an Abaqus UMAT plays. One microstructure stands for one material point: the FE code hands over a strain, the package hands back a stress and a consistent tangent.</p><div class="warning custom-block"><p class="custom-block-title">Two opposite couplings — this is not the finite-element inclusion</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">who calls whom</th><th style="text-align:left;">what it produces</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/manual/fe_inclusions#man-fe-inclusions">Finite-element inclusions</a></td><td style="text-align:left;"><strong>MFH calls</strong> the FE solver</td><td style="text-align:left;">one inclusion&#39;s response, when no closed form exists</td></tr><tr><td style="text-align:left;">This section</td><td style="text-align:left;"><strong>the FE code calls MFH</strong></td><td style="text-align:left;">a material law at every Gauss point</td></tr></tbody></table></div>',3)),(e(),s(h,null,{default:l(()=>[c(n,{id:"mermaid-47",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22flowchart%22%3A%20%7B%22useMaxWidth%22%3A%20false%2C%20%22nodeSpacing%22%3A%2030%2C%20%22rankSpacing%22%3A%2040%7D%7D%20%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20subgraph%20FE%5B%22structure%20scale%20%E2%80%94%20the%20FE%20code%22%5D%0A%20%20%20%20%20%20%20%20MESH%5B%22mesh%2C%20element%20loop%22%5D%0A%20%20%20%20%20%20%20%20QP%5B%22quadrature%20point%3A%3Cbr%2F%3Estrain%20%F0%9D%9B%86%2C%20state%22%5D%0A%20%20%20%20%20%20%20%20ASM%5B%22assemble%20residual%3Cbr%2F%3Eand%20Jacobian%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20MFH%5B%22material%20point%20%E2%80%94%20MeanFieldHomogenization%22%5D%0A%20%20%20%20%20%20%20%20RVE%5B%22RVE%3A%20matrix%20%2B%20inclusions%3Cbr%2F%3E%2B%20crack%20families%22%5D%0A%20%20%20%20%20%20%20%20SCH%5B%22scheme%3Cbr%2F%3EMT%2C%20self-consistent%2C%20%E2%80%A6%22%5D%0A%20%20%20%20%20%20%20%20HOM%5B%22%E2%84%82%CA%B0%E1%B5%92%E1%B5%90%2C%20%F0%9D%90%81%2C%201%2FM%2C%20%F0%9D%90%8A%CA%B0%E1%B5%92%E1%B5%90%22%5D%0A%20%20%20%20end%0A%20%20%20%20MESH%20--%3E%20QP%0A%20%20%20%20QP%20--%3E%7C%22%F0%9D%9B%86%2C%20internal%20state%22%7C%20RVE%0A%20%20%20%20RVE%20--%3E%20SCH%20--%3E%20HOM%0A%20%20%20%20HOM%20--%3E%7C%22%F0%9D%9B%94%2C%20%E2%88%82%F0%9D%9B%94%2F%E2%88%82%F0%9D%9B%86%2C%20new%20state%22%7C%20ASM%0A%20%20%20%20ASM%20--%3E%20MESH%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="Why-bother" tabindex="-1">Why bother <a class="header-anchor" href="#Why-bother" aria-label="Permalink to &quot;Why bother {#Why-bother}&quot;">​</a></h2><p>A closed-form law is written once and fitted to data. A homogenized law is <em>derived</em> from the microstructure, so the same computation also tells you what each phase is doing — and lets the microstructure evolve. That is what makes the fractured-reservoir model of [<a href="/MeanFieldHomogenization.jl/v0.10/references#barthelemyARMA2011">71</a>] possible: fracture apertures follow the effective stress, and the permeability follows the apertures.</p><h2 id="Reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#Reading-order" aria-label="Permalink to &quot;Reading order {#Reading-order}&quot;">​</a></h2><p>Three groups, read in this order: the equations, then how to build a model with them, then worked models.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Theory</strong></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/scale_transition#fe-scale-transition">Scale transition</a></td><td style="text-align:left;">the equations: incremental format, consistent tangent, tangent blocks</td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/poroelastic_coupling#fe-poro-coupling">The coupled poroelastic problem</a></td><td style="text-align:left;">the same, with a fluid: two balances, the Biot blocks, the four tangents</td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/permeability#fe-permeability">Fractured permeability</a></td><td style="text-align:left;">flowing cracks and the effective conductivity of a fracture network</td></tr><tr><td style="text-align:left;"><strong>Manual</strong></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/materials#fe-materials">Materials</a></td><td style="text-align:left;">the Gauss-point contract, in code</td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/fractured_rock#fe-fractured-rock">Building a fractured-rock material</a></td><td style="text-align:left;">the ARMA 2011 material: two gradients, two fluxes, evolving permeability</td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/backends#fe-backends">Ferrite backend</a></td><td style="text-align:left;">the three helpers a Ferrite driver needs</td></tr><tr><td style="text-align:left;"><strong>Examples</strong></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/thick_cylinder#fe-thick-cylinder">Thick-walled cylinder</a></td><td style="text-align:left;">worked model, checked against Lamé, then with closing cracks</td></tr><tr><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.10/fe_coupling/arma2011#fe-arma2011">A fractured-reservoir well test</a></td><td style="text-align:left;">the ARMA 2011 well test, end to end</td></tr></tbody></table><p>The Biot machinery the poroelastic coupling builds on is a property of a microstructure rather than of the coupling, so it lives on its own page: <a href="/MeanFieldHomogenization.jl/v0.10/manual/poromechanics#manual-poromechanics">Poromechanics</a>.</p>',6))])}const _=i(f,[["render",g]]);export{A as __pageData,_ as default};
